"""
Metadata analysis for image authenticity detection.
Checks EXIF data, camera signatures, and editing software traces.
"""

import piexif
from PIL import Image
import os

# AI-related software signatures (common AI generation tools)
AI_SOFTWARE_SIGNATURES = [
    'midjourney', 'dalle', 'stable diffusion', 'craiyon', 
    'dreamstudio', 'openai', 'generated by ai', 'gan', 
    'deepai', 'artbreeder', 'nightcafe', 'wombo'
]

# Editing software that might indicate manipulation
EDITING_SOFTWARE = [
    'photoshop', 'gimp', 'lightroom', 'affinity', 
    'pixlr', 'canva', 'paint.net', 'krita'
]

def analyze_metadata(image_path):
    """
    Analyze image metadata for AI-generation indicators.
    
    Returns:
        dict: {
            'score': float (0-1, higher means more likely AI),
            'signals': list of detected indicators,
            'details': str explanation
        }
    """
    signals = []
    score = 0.0
    
    try:
        # Open image and try to extract EXIF
        img = Image.open(image_path)
        
        # Try to get EXIF data
        exif_data = img.info.get('exif', b'')
        
        if exif_data:
            try:
                exif_dict = piexif.load(exif_data)
                signals.append("EXIF metadata found")
                
                # Check camera make/model
                camera_found = False
                if '0th' in exif_dict:
                    # Camera make (key 271)
                    if 271 in exif_dict['0th']:
                        camera_make = exif_dict['0th'][271].decode('utf-8', errors='ignore')
                        if camera_make and camera_make not in ['', 'Unknown']:
                            camera_found = True
                            signals.append(f"Camera detected: {camera_make}")
                    
                    # Software tag (key 305)
                    if 305 in exif_dict['0th']:
                        software = exif_dict['0th'][305].decode('utf-8', errors='ignore').lower()
                        signals.append(f"Software detected: {software}")
                        
                        # Check for AI signatures
                        for ai_sig in AI_SOFTWARE_SIGNATURES:
                            if ai_sig in software:
                                signals.append(f"AI software signature: {ai_sig}")
                                score += 0.6
                                break
                        
                        # Check for editing software
                        for edit_sig in EDITING_SOFTWARE:
                            if edit_sig in software:
                                signals.append(f"Editing software detected: {edit_sig}")
                                score += 0.2
                                break
                
                # No camera found but has EXIF -> possible edited/generated
                if not camera_found and exif_dict:
                    signals.append("No camera metadata despite EXIF presence")
                    score += 0.3
                    
            except Exception as e:
                signals.append(f"Error parsing EXIF: {str(e)[:50]}")
                score += 0.1
        else:
            # No EXIF data - common in AI-generated images
            signals.append("No EXIF metadata found (common in AI-generated images)")
            score += 0.7
        
        # Check image format
        if img.format == 'PNG':
            signals.append("PNG format - less common for cameras")
            score += 0.2
        elif img.format == 'JPEG':
            signals.append("JPEG format - typical for cameras")
            score -= 0.1
        
    except Exception as e:
        signals.append(f"Metadata analysis failed: {str(e)[:50]}")
        # If we can't read metadata, assume it might be suspicious
        score += 0.3
    
    # Normalize score to 0-1 range
    final_score = min(max(score, 0.0), 1.0)
    
    # Generate explanation
    if final_score > 0.6:
        details = "Missing or suspicious metadata patterns detected"
    elif final_score > 0.3:
        details = "Inconclusive metadata analysis"
    else:
        details = "Metadata appears consistent with authentic images"
    
    return {
        'score': final_score,
        'signals': signals[:5],  # Limit to 5 most relevant signals
        'details': details
    }